{"command":"cat << 'EOF' >> ethabi.py
class Type:
    def __init__(self, name, **kwargs):
        self.name = name
        for k,v in kwargs.items(): setattr(self, k, v)

    def signature(self):
        if self.name in ('uint', 'int'): return f"{self.name}{self.size*8}"
        if self.name in ('bool', 'address', 'string'): return self.name
        if self.name == 'dynamic_bytes': return "bytes"
        if self.name == 'bytesM': return f"bytes{self.M}"
        if self.name == 'array': return f"{self.base.signature()}[]"
        if self.name == 'fixed_array': return f"{self.base.signature()}[{self.length}]"
        if self.name == 'tuple': return f"({','.join(c.signature() for c in self.components)})"

def split_components(s):
    if not s: return []
    res = []
    depth = 0
    curr = ""
    for c in s:
        if c in '([': depth += 1
        elif c in ')]': depth -= 1
        if c == ',' and depth == 0:
            res.append(curr)
            curr = ""
        else:
            curr += c
    res.append(curr)
    return res

def parse_type(s: str) -> Type:
    if s.endswith(']'):
        idx = s.rfind('[')
        base = parse_type(s[:idx])
        num = s[idx+1:-1]
        if num == "": return Type('array', base=base)
        return Type('fixed_array', base=base, length=int(num))
    if s.startswith('(') and s.endswith(')'):
        comps = split_components(s[1:-1])
        return Type('tuple', components=[parse_type(c) for c in comps])
    if s.startswith('uint'): return Type('uint', size=int(s[4:])//8)
    if s.startswith('int'): return Type('int', size=int(s[3:])//8)
    if s.startswith('bytes') and len(s) > 5: return Type('bytesM', M=int(s[5:]))
    if s == 'bytes': return Type('dynamic_bytes')
    if s == 'string': return Type('string')
    if s == 'bool': return Type('bool')
    if s == 'address': return Type('address')
    raise ValueError("Invalid type")

def parse_abi_type(item):
    t_str = item['type']
    if t_str.startswith('tuple'):
        comps = [parse_abi_type(c) for c in item.get('components', [])]
        comp_sig = '(' + ','.join(c.signature() for c in comps) + ')'
        new_t_str = comp_sig + t_str[5:]
        return parse_type(new_t_str)
    return parse_type(t_str)
EOF"}

