def encode_tuple(types, values):
    head = []
    tail = b''
    offset = sum(head_size(t) for t in types)
    for t, v in zip(types, values):
        if is_dynamic(t):
            head.append(offset.to_bytes(32, 'big'))
            encoded = encode_type(t, v)
            tail += encoded
            offset += len(encoded)
        else:
            encoded = encode_type(t, v)
            head.append(encoded)
    return b''.join(head) + tail

def encode_type(t, v):
    if t.name == 'uint': return v.to_bytes(32, 'big')
    if t.name == 'int': return ((1<<256)+v if v<0 else v).to_bytes(32, 'big')
    if t.name == 'bool': return b'\x00'*31 + (b'\x01' if v else b'\x00')
    if t.name == 'address': return b'\x00'*12 + v
    if t.name == 'bytesM': return v + b'\x00'*(32 - len(v))
    if t.name == 'dynamic_bytes':
        length = len(v).to_bytes(32, 'big')
        padded = v + b'\x00'*((32 - (len(v)%32))%32) if len(v) % 32 != 0 else v
        return length + padded
    if t.name == 'string':
        v = v.encode('utf-8')
        length = len(v).to_bytes(32, 'big')
        padded = v + b'\x00'*((32 - (len(v)%32))%32) if len(v) % 32 != 0 else v
        return length + padded
    if t.name == 'array':
        length = len(v).to_bytes(32, 'big')
        return length + encode_tuple([t.base]*len(v), v)
    if t.name == 'fixed_array':
        return encode_tuple([t.base]*t.length, v)
    if t.name == 'tuple':
        return encode_tuple(t.components, v)

def decode_tuple(types, data, offset=0):
    values = []
    current_head = offset
    for t in types:
        if is_dynamic(t):
            dyn_offset = int.from_bytes(data[current_head:current_head+32], 'big')
            values.append(decode_type(t, data, offset + dyn_offset))
            current_head += 32
        else:
            values.append(decode_type(t, data, current_head))
            current_head += head_size(t)
    return values

def decode_type(t, data, offset):
    if t.name == 'uint': return int.from_bytes(data[offset:offset+32], 'big')
    if t.name == 'int': 
        val = int.from_bytes(data[offset:offset+32], 'big')
        return val - (1<<256) if val >= (1<<255) else val
    if t.name == 'bool': return data[offset+31] != 0
    if t.name == 'address': return data[offset+12:offset+32].hex()
    if t.name == 'bytesM': return data[offset:offset+t.M].hex()
    if t.name == 'dynamic_bytes':
        length = int.from_bytes(data[offset:offset+32], 'big')
        return data[offset+32:offset+32+length].hex()
    if t.name == 'string':
        length = int.from_bytes(data[offset:offset+32], 'big')
        return data[offset+32:offset+32+length].decode('utf-8', 'replace')
    if t.name == 'array':
        length = int.from_bytes(data[offset:offset+32], 'big')
        return decode_tuple([t.base]*length, data, offset+32)
    if t.name == 'fixed_array':
        return decode_tuple([t.base]*t.length, data, offset)
    if t.name == 'tuple':
        return decode_tuple(t.components, data, offset)

def format_value(t, v) -> str:
    if t.name in ('uint', 'int'): return str(v)
    if t.name == 'bool': return "true" if v else "false"
    if t.name in ('address', 'bytesM', 'dynamic_bytes', 'string'): return v
    if t.name in ('array', 'fixed_array'): return "[" + ",".join(format_value(t.base, el) for el in v) + "]"
    if t.name == 'tuple': return "(" + ",".join(format_value(c, el) for c, el in zip(t.components, v)) + ")"

